  MP.pulSecimi = function () {
    let s = Math.round(MP.oku("pulSahip2", -1));
    if (s < 0) { s = 0; const e = Math.round(MP.oku("pulSahip", 0)); for (let i = 3; i < 10; i++) if ((e & (1 << i)) && MP.ESKI[i] >= 8) s |= (1 << (MP.ESKI[i] - 8)); }
    const s3 = Math.round(MP.oku("pulSahip3", 0)), KALK = [9, 12, 13, 14, 24, 28, 29, 30];
    const gec = (x) => (x >= 0 && x <= 7) || (x >= 8 && x <= 31 && !KALK.includes(x) && !!(s & (1 << (x - 8)))) || (x >= 32 && x <= 44 && !!(s3 & (1 << (x - 32))));
    let a = Math.round(MP.oku("anaPul2", -1)), y = Math.round(MP.oku("yedekPul2", -1));
    if (a < 0) { const e = Math.round(MP.oku("anaPul", 0)); a = MP.ESKI[e] >= 0 ? MP.ESKI[e] : 0; }
    if (y < 0) { const e = Math.round(MP.oku("yedekPul", 2)); y = MP.ESKI[e] >= 0 ? MP.ESKI[e] : 2; }
    if (!gec(a)) a = 0;
    if (!gec(y) || y === a) y = a === 2 ? 0 : 2;
    return [a, y];
  };
  // iki pulun ana renkleri birbirine çok mu yakın? (bilgisayar rakibin rengini seçerken)
  MP.benzer = function (i, j) {
    const a = (MP.RENK[i] || "0;0;0").split(";").map(Number), b = (MP.RENK[j] || "0;0;0").split(";").map(Number);
    return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]) < 120;
  };
  MP.DEPO = "matranc";
