    const tik = "<svg width='18' height='18' viewBox='0 0 24 24'><path d='M4 12.5l5 5L20 6.5' fill='none' stroke='#3aa557' stroke-width='3.6' stroke-linecap='round' stroke-linejoin='round'/></svg>";
